head.script:
// https://inswave01.atlassian.net/browse/WAEA-1427

// 테스트 설명, 유효성 값 설정
//  담당 범위 : _1 = 기본 동작(동작 inputType / 파라미터 / 반환값 / 적용 순서 / DataList 미반영 / select 라벨)
//              _2 = escape / embeddedInput 의 HTML 해석, _3 = spinner
scwin.tData = {
    "description" : "[column > P > customFormatter]<br/>Column 이 편집 상태가 아닐때 표시될 Column 값을 반환하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "Column 의 inputType='text', 'link', 'textImage', 'textarea', 'select', 'expression' 인 경우에 동작합니다.",
        "함수 이름 설정 시, 사용자 정의 함수의 파라미터로 원본 Column 값, 포맷된 Column 값, Row 인덱스, Column 인덱스 값이 전달됩니다.",
        "함수 이름 설정 시, 사용자 정의 함수의 반환값이 Column 에 표시되는 값으로 적용됩니다.",
        "표시되는 Column 값을 만드는 displayFormat, displayFormatter 등의 속성 중 가장 마지막에 적용되어 최종 Column 값을 결정합니다. 다른 속성에 의해 적용된 Column 표시값은 두번째 파라미터로 전달되며, 두번째 파라미터를 사용하지 않고 첫번째 파라미터만 사용하면 적용된 포맷과 마스킹이 사라집니다.",
        "사용자 함수의 반환값은 Column 값 표시에만 사용되며 DataList 에 반영되지 않습니다.",
        "inputType='select' 인 Column 은 두번째 파라미터에 포맷된 Column 값이 아닌 선택 아이템의 라벨값이 전달됩니다.",
    ]
}



scwin.gVar = {
    // Row 인덱스별 사용자 함수 호출 파라미터 (재생성 시 초기화)
    "params" : {}
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_inputType.setValue("text");
    con_customFormatter.setValue("scwin.fmt_formattedData");
    con_format.setValue("displayFormat");
    scwin.con_inputType_onviewchange();

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 사용자 정의 함수 : 두번째 파라미터(포맷된 값)를 사용
scwin.fmt_formattedData = function (data, formattedData, rowIndex, columnIndex) {
    scwin.gVar.params[rowIndex] = "(" + data + ", " + formattedData + ", " + rowIndex + ", " + columnIndex + ")";
    return "★ " + formattedData;
}



// 사용자 정의 함수 : 첫번째 파라미터(원본 값)만 사용
scwin.fmt_data = function (data, formattedData, rowIndex, columnIndex) {
    scwin.gVar.params[rowIndex] = "(" + data + ", " + formattedData + ", " + rowIndex + ", " + columnIndex + ")";
    return "★ " + data;
}



// displayFormatter 로 지정하는 표시 포맷 함수 (천 단위 구분 + 원 단위 표시)
scwin.formatter_won = function (value) {
    if (value === "" || value === null || typeof value === "undefined") {
        return value;
    }
    return WebSquare.text.formatCurrency(String(value), "#,###") + " 원";
}



// select / calendar 는 표시 포맷 조건 미사용
scwin.con_inputType_onviewchange = function () {
    let cInputType = con_inputType.getValue();
    con_format.setDisabled(cInputType === "select" || cInputType === "calendar");
}



// inputType 별 바인딩 데이터 (val)
scwin.getValData = function (cInputType) {
    if (cInputType === "select") {
        return ["A", "B", "C", "A"];
    }
    if (cInputType === "calendar") {
        return ["20260105", "20260212", "20260320", "20260418"];
    }
    return ["1250000", "320000", "89000", "45000"];
}



// 검증 대상 Column(Body Column 인덱스 2) 마크업
scwin.getTargetColumn = function (cInputType, cFormatter) {
    let cFormat = con_format.getValue();
    let attr = (cFormatter === '') ? '' : ' customFormatter="' + cFormatter + '"';
    if (cInputType !== "select" && cInputType !== "calendar") {
        if (cFormat === "displayFormat") {
            attr += ' dataType="number" displayFormat="#,###"';
        } else if (cFormat === "displayFormatter") {
            attr += ' dataType="number" displayFormatter="scwin.formatter_won"';
        }
    }
    let col = '';
    if (cInputType === "select") {
        col += '<w2:column width="200" style="" inputType="select" id="val"' + attr + '>';
        col += '<w2:choices>';
        col += '<w2:item><w2:label><![CDATA[최우수]]' + '></w2:label><w2:value><![CDATA[A]]' + '></w2:value></w2:item>';
        col += '<w2:item><w2:label><![CDATA[우수]]' + '></w2:label><w2:value><![CDATA[B]]' + '></w2:value></w2:item>';
        col += '<w2:item><w2:label><![CDATA[보통]]' + '></w2:label><w2:value><![CDATA[C]]' + '></w2:value></w2:item>';
        col += '</w2:choices>';
        col += '</w2:column>';
    } else if (cInputType === "expression") {
        // 수량 x 12,500 계산값 표시 (DataList 에 없는 Column)
        col += '<w2:column width="200" style="" inputType="expression" id="expr" expression="Number(display(\'qty\'))*12500"' + attr + '></w2:column>';
    } else if (cInputType === "textImage") {
        col += '<w2:column width="200" style="" inputType="textImage" id="val" imageSrc="/cm/images/contents/btn_folder.png"' + attr + '></w2:column>';
    } else {
        col += '<w2:column width="200" style="" inputType="' + cInputType + '" id="val"' + attr + '></w2:column>';
    }
    return col;
}



// comp 생성
//  - name : 상품명 / qty : 수량 / val(expression 은 expr) : 검증 대상 Column (Body Column 인덱스 2)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.params = {};

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 사용자 정의 함수는 검증 Column(Body Column 인덱스 2) 에 설정, displayFormat 은 #,### / displayFormatter 는 천 단위 + 원 (select, calendar 는 표시 포맷 미적용)\n[절차] 조건 선택 -> Target 재생성 -> 결과창의 함수 파라미터 (원본값, 포맷된 값, Row, Column) 와 화면 표시값 확인\n[확인] DataList 값 확인 버튼으로 바인딩 DataList 값과 화면 표시값 비교"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cInputType = con_inputType.getValue();
    let cFormatter = con_customFormatter.getValue();

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="qty" name="qty" dataType="text"></w2:column>';
    strDlt += '<w2:column id="val" name="val" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    let names = ["노트북", "모니터", "키보드", "마우스"];
    let qtys = ["3", "12", "40", "8"];
    let vals = scwin.getValData(cInputType);
    let jsonData = [];
    for (let i = 0; i < names.length; i++) {
        jsonData.push({ "name" : names[i], "qty" : qtys[i], "val" : vals[i] });
    }
    dlt_bind.setJSON(jsonData, false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="상품명"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="수량"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column3" value="값(' + cInputType + ')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="qty" value=""></w2:column>';
    strTarget += scwin.getTargetColumn(cInputType, cFormatter);
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    setTimeout(function () {
        // validation 2, 4, 6 : 함수에 전달된 파라미터 (원본값, 포맷된 값, Row 인덱스, Column 인덱스)
        let arr = [];
        for (let i = 0; i < dlt_bind.getRowCount(); i++) {
            if (scwin.gVar.params[i]) {
                arr.push(scwin.gVar.params[i]);
            }
        }
        if (arr.length > 0) {
            wf_body_bottom.getObj("scwin").setReturnValue("함수 파라미터 (원본값, 포맷된 값, Row, Column) : " + arr.join(" / "));
        }
        // validation 1, 3, 4 : 행별 화면 표시값
        wf_body_bottom.getObj("scwin").setReturnValue("화면 표시값 : " + scwin.getAllDisplayStr());
    }, 100);
}



// 검증 Column(인덱스 2) 의 행별 화면 표시값
scwin.getAllDisplayStr = function () {
    let arr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + i + "_2']");
        arr.push(i + "행='" + (td ? td.textContent.trim() : "") + "'");
    }
    return arr.join(" / ");
}



// validation 5 : 바인딩 DataList 값과 화면 표시값 비교 (expression 은 DataList 에 Column 이 없어 계산 원본인 qty 출력)
scwin.btn_checkDataList_onclick = function () {
    let colId = (con_inputType.getValue() === "expression") ? "qty" : "val";
    let arr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        arr.push(i + "행='" + dlt_bind.getCellData(i, colId) + "'");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("DataList " + colId + " : " + arr.join(" / ") + "\n화면 표시값 : " + scwin.getAllDisplayStr());
}
